def test_get_branches_success(api_url, sample_project_slug, workflow_name, valid_headers):
    """
    Test the GET /insights/{project-slug}/branches endpoint with valid authentication.
    """
    url = f"{api_url}/{sample_project_slug}/branches"
    params = {}
    if workflow_name:
        params["workflow-name"] = workflow_name
    
    response = requests.get(url, headers=valid_headers, params=params)
    
    assert response.status_code == 200, f"Unexpected status code {response.status_code}"
